// n8n hands this node details about whatever went wrong.
// We pull out the useful bits and turn them into a plain email.
const err = ($json.execution && $json.execution.error) || {};
const wf = $json.workflow || {};
const failedNode = ($json.execution && $json.execution.lastNodeExecuted) || 'Unknown node';
const executionUrl = ($json.execution && $json.execution.url) || '';

const subject = `\u26a0\ufe0f WhatsApp Bot stopped working: ${wf.name || 'Workflow'}`;

const body = `The WhatsApp bot workflow ran into a problem and stopped.

Workflow: ${wf.name || 'Unknown'}
It stopped at this step: ${failedNode}
Error message: ${err.message || 'No message provided'}
When: ${new Date().toISOString()}

${executionUrl ? 'Open this link to see exactly what happened: ' + executionUrl : 'Open n8n and check the Executions tab to see exactly what happened.'}

This usually means one of these needs attention:
- A WhatsApp, Google, or Groq access token expired
- One of those services is briefly down
- Someone changed a node and it needs reconnecting`;

return { json: { subject, body } };
